import sys
from abc import ABC, abstractmethod

class Employee(ABC):
    @abstractmethod
    def calculateSalary(self):
        pass

    @abstractmethod
    def getDetails(self):
        pass

class FullTimeEmployee(Employee):
    def __init__(self, name, monthlySalary):
        self.name = name
        self.monthlySalary = monthlySalary

    def calculateSalary(self):
        return self.monthlySalary

    def getDetails(self):
        return f"Name: {self.name}, Salary: {self.monthlySalary}"

class PartTimeEmployee(Employee):
    def __init__(self, name, hourlyRate, hoursWorked):
        self.name = name
        self.hourlyRate = hourlyRate
        self.hoursWorked = hoursWorked

    def calculateSalary(self):
        return self.hourlyRate * self.hoursWorked

    def getDetails(self):
        return f"Name: {self.name}, Salary: {self.calculateSalary()}"

def main():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    if not lines:
        return

    idx = 0
    results = []

    while idx < len(lines):
        emp_type = lines[idx]
        idx += 1

        if emp_type == "FullTimeEmployee":
            name = lines[idx]
            idx += 1
            salary = float(lines[idx])
            idx += 1
            emp = FullTimeEmployee(name, salary)
            results.append(emp.getDetails())
        elif emp_type == "PartTimeEmployee":
            name = lines[idx]
            idx += 1
            hourly_rate = float(lines[idx])
            idx += 1
            hours_worked = int(lines[idx])
            idx += 1
            emp = PartTimeEmployee(name, hourly_rate, hours_worked)
            results.append(emp.getDetails())

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
